using Microsoft.EntityFrameworkCore;
class AppDbContext : DbContext
{
    public DbSet<Order> Orders => Set<Order>();
    protected override void OnModelCreating(ModelBuilder modelBuilder)
    {
        // Breaking change: HasData with DateTime.UtcNow is non-deterministic and was
        // always problematic; use a fixed value to avoid migration churn.
        modelBuilder.Entity<Order>().HasData(
            new Order { Id = 1, CreatedAt = new DateTime(2024, 1, 1, 0, 0, 0, DateTimeKind.Utc) });
    }
}
class Order { public int Id { get; set; } public DateTime CreatedAt { get; set; } }

// --- Cosmos DB context demonstrating EF Core 9 breaking-change fixes ---

class CosmosDbContext : DbContext
{
    public DbSet<Product> Products => Set<Product>();

    protected override void OnConfiguring(DbContextOptionsBuilder options)
        => options.UseCosmos(
            "AccountEndpoint=https://localhost:8081/;AccountKey=dummy",
            "ShopDb");

    protected override void OnModelCreating(ModelBuilder modelBuilder)
    {
        // Breaking change #1 (EF Core 9): The Cosmos provider now uses
        // "$type" as the default discriminator property name instead of "Discriminator".
        // Existing documents still store "Discriminator", so we must explicitly configure it.
        modelBuilder.Entity<Product>(b =>
        {
            b.HasDiscriminator<string>("Discriminator");
            b.ToContainer("Products");
            b.HasPartitionKey(p => p.Category);
        });
    }
}

class Product
{
    public string Id { get; set; } = null!;
    public string Name { get; set; } = null!;
    public string Category { get; set; } = null!;
}

// --- Service demonstrating sync-to-async migration ---

class ProductService
{
    private readonly CosmosDbContext _db;
    public ProductService(CosmosDbContext db) => _db = db;

    // Breaking change #2 (EF Core 9): Synchronous I/O is no longer supported
    // by the Cosmos DB provider. All queries/saves must use async methods.
    public async Task<List<Product>> GetProductsAsync(string category)
    {
        return await _db.Products
            .Where(p => p.Category == category)
            .ToListAsync();
    }

    public async Task AddProductAsync(Product product)
    {
        _db.Products.Add(product);
        await _db.SaveChangesAsync();
    }
}

